CREATE TABLE `ourlink_db1`.`bib_dh_page` ( `PageNumber` INT NOT NULL , `FileName` VARCHAR(50) NOT NULL , `ReferenceNumber` INT NULL DEFAULT NULL , `StartDhNumber` INT NULL DEFAULT NULL , `EndDhNumber` INT NULL DEFAULT NULL , PRIMARY KEY (`PageNumber`)) ENGINE = InnoDB CHARSET=utf8 COLLATE utf8_unicode_ci;
ALTER TABLE `bib_dh_page` ADD `HeaderText` VARCHAR(500) NULL DEFAULT NULL AFTER `EndDhNumber`, ADD `WidthInPixels` INT NULL DEFAULT NULL AFTER `HeaderText`, ADD `HeightInPixels` INT NULL DEFAULT NULL AFTER `WidthInPixels`, ADD `FullTextFileName` VARCHAR(255) NULL DEFAULT NULL AFTER `HeightInPixels`, ADD `FullTextOCR` TEXT NULL DEFAULT NULL AFTER `FullTextFileName`;
